import {planetArt} from './art.js';
import { escapeHtml as h, number } from './domain.js';
const errorBox='<p class="form-error" role="alert" hidden></p>';
export function clanMembersView(data,compact=false){
 if(!data?.clan)return '';
 return `<details class="clan-roster ${compact?'compact':''}" open><summary>Membres du clan · ${number(data.members.length)}</summary><div class="clan-members">${data.members.map(m=>`<article class="clan-member"><header><span><small>${h(m.grade)}</small><b>${h(m.username)}</b></span>${m.role==='founder'?'<strong>Chef du clan</strong>':''}</header><div class="clan-member-worlds">${m.planets.length?m.planets.map(p=>`<span class="clan-member-world"><img src="${planetArt(p.appearance,true)}" alt="" width="28" height="28"><span>${h(p.name)}${p.tagged?` <b>[${h(data.clan.name)}]</b>`:''}<small class="${p.tagged?'public-tag':'hidden-tag'}">${p.tagged?'Tag public':'Non taguée'}</small></span></span>`).join(''):'<small>Aucune planète contrôlée.</small>'}</div></article>`).join('')}</div></details>`;
}
function incomingRequests(data){return data?.clan?.role==='founder'?`<section class="clan-incoming"><h4>Candidatures entrantes · ${number(data.incoming.length)}</h4>${data.incoming.length?data.incoming.map(r=>`<article class="clan-request"><span><small>${h(r.grade)}</small><b>${h(r.username)}</b></span><div>${[[true,'Accepter'],[false,'Refuser']].map(([accept,label])=>`<form data-clan-action="review" data-request-id="${h(r.id)}" data-accept="${accept}">${errorBox}<button class="secondary" type="submit">${label}</button></form>`).join('')}</div></article>`).join(''):'<p class="form-note">Aucune candidature en attente.</p>'}</section>`:'';}
export function clanPanel(clan, clans,data) {
  if(clan) return `<section class="clan-section" aria-labelledby="clan-title"><div class="eyebrow">ALLÉGEANCE · SESSION ALPHA</div><h3 id="clan-title">Votre clan</h3><div class="clan-standard"><span class="clan-crest" aria-hidden="true">◇</span><div><strong>[${h(clan.name)}]</strong><p>${clan.role==='founder'?'Chef du clan':'Membre'} · ${number(clan.member_count)} ${clan.member_count>1?'membres':'membre'}</p></div></div><p>Chaque planète décide de son identité publique. Activez son tag dans la page Planètes, ou gardez votre affiliation masquée.</p>${clanMembersView(data)}${incomingRequests(data)}<form data-clan-action="leave" data-clan-id="${h(clan.id)}">${errorBox}<button class="secondary" type="submit">Quitter le clan</button><p class="form-note">Vos tags seront masqués. Le fondateur transmet son rôle au membre le plus ancien ; le dernier départ dissout le clan.</p></form></section>`;
  if(data?.outgoing?.length)return `<section class="clan-section"><div class="eyebrow">ALLÉGEANCE</div><h3>Candidature en attente</h3>${data.outgoing.map(r=>`<div class="clan-request"><p>Votre candidature à <b>[${h(r.clan_name)}]</b> attend la décision du chef.</p><form data-clan-action="cancel-request" data-request-id="${h(r.id)}">${errorBox}<button class="secondary" type="submit">Annuler ma candidature</button></form></div>`).join('')}</section>`;
  return `<section class="clan-section" aria-labelledby="clan-title"><div class="eyebrow">ALLÉGEANCE · SESSION ALPHA</div><h3 id="clan-title">Votre prochaine alliance</h3><p>Créez votre clan ou rejoignez un clan existant. Un seul clan à la fois ; aucune affiliation n’est affichée automatiquement sur vos planètes.</p><div class="clan-choices"><form data-clan-action="create"><h4>Créer un clan</h4><label class="field">Nom du clan<input name="clan_name" required minlength="3" maxlength="24" placeholder="Ex. Les Veilleurs" autocomplete="off"></label><p class="form-note">3 à 24 caractères. Le nom apparaîtra sous la forme [Nom du clan].</p>${errorBox}<button class="primary" type="submit">Créer mon clan <span aria-hidden="true">→</span></button></form><form data-clan-action="join"><h4>Rejoindre un clan</h4>${clans.length?`<label class="field">Clans de la session<select name="clan_id" required><option value="">Choisir un clan</option>${clans.map(c=>`<option value="${h(c.id)}">${h(c.name)}</option>`).join('')}</select></label><p class="form-note">Votre candidature doit être acceptée par le chef du clan. L’annuaire des membres et le forum privé deviennent accessibles après acceptation.</p>${errorBox}<button class="secondary" type="submit">Envoyer ma candidature</button>`:'<p class="clan-empty">Aucun clan pour le moment.<br>Tracez la première bannière parmi les étoiles.</p>'}</form></div></section>`;
}
export function planetOptions(planet,clan){return `<section class="planet-options" aria-labelledby="planet-options-title"><div><div class="eyebrow">IDENTITÉ & ÉCHANGES</div><h3 id="planet-options-title">Clan & commerce</h3></div><form id="planet-options-form"><label class="option-row"><input name="clan_tag" type="checkbox" ${planet.clan_tag_visible?'checked':''} ${!clan||new Date(planet.anonymous_until)>Date.now()?'disabled':''}><span><strong>Afficher ${clan?`[${h(clan.name)}]`:'mon clan'} sur cette planète</strong><small>${new Date(planet.anonymous_until)>Date.now()?'Affiliation masquée pendant le contrôle anonyme.':clan?'Le nom et le clan seront visibles sur la carte. Désactivez pour masquer son appartenance au clan.':'Rejoignez ou créez un clan dans Compte & clan pour activer un tag.'}</small></span></label><label class="option-row"><input name="auto_trade" type="checkbox" ${planet.auto_trade?'checked':''}><span><strong>Commerce automatique</strong><small>Activé par défaut. Désactivez pour examiner les demandes entrantes avant acceptation.</small></span></label><p class="form-note">Les liaisons déjà actives restent ouvertes si vous passez en validation manuelle.</p>${errorBox}<button class="secondary" type="submit">Enregistrer les options</button></form></section>`;}
